def date_public_pieces(apps, schema_editor):
    """Antes de exigir fecha a lo público: lo publicado o archivado sin fecha toma la de su
    última edición, y lo programado sin fecha vuelve a aprobado (sin fecha no saldría nunca),
    con su entrada en la bitácora."""
    ContentType = apps.get_model("contenttypes", "ContentType")
    EditorialTransition = apps.get_model("content", "EditorialTransition")
    for name in ("article", "poem"):
        model = apps.get_model("content", name)
        model.objects.filter(
            status__in=["published", "archived"], published_at__isnull=True
        ).update(published_at=models.F("updated_at"))
        undated = list(
            model.objects.filter(status="scheduled", published_at__isnull=True).values_list(
                "pk", flat=True
            )
        )
        if not undated:
            continue
        content_type = ContentType.objects.get(app_label="content", model=name)
        model.objects.filter(pk__in=undated).update(status="approved")
        EditorialTransition.objects.bulk_create(
            EditorialTransition(
                content_type=content_type,
                object_id=pk,
                from_status="scheduled",
                to_status="approved",
                note="Programada sin fecha: vuelve a aprobada.",
            )
            for pk in undated
        )


